#!/usr/bin/env bash
set -euo pipefail

ENV_FILE="$(cd "$(dirname "$0")" && pwd)/.env"

generate_password() {
  openssl rand -base64 32 | tr -d '/+=' | head -c 32
}

if [ -f "$ENV_FILE" ]; then
  echo ".env already exists at $ENV_FILE"
  echo "To regenerate, delete it first: rm $ENV_FILE"
  exit 0
fi

POSTGRES_PASSWORD=$(generate_password)
REDIS_PASSWORD=$(generate_password)
JWT_SECRET=$(generate_password)
JWT_REFRESH_SECRET=$(generate_password)

cat > "$ENV_FILE" <<EOF
# Auto-generated by setup.sh — $(date -u '+%Y-%m-%dT%H:%M:%SZ')
# Do NOT commit this file to git.

# PostgreSQL
POSTGRES_USER=synapse
POSTGRES_PASSWORD=$POSTGRES_PASSWORD
POSTGRES_DB=synapse

# Redis
REDIS_PASSWORD=$REDIS_PASSWORD

# JWT
JWT_SECRET=$JWT_SECRET
JWT_REFRESH_SECRET=$JWT_REFRESH_SECRET

# Application URLs (constructed from above)
DATABASE_URL=postgresql://synapse:${POSTGRES_PASSWORD}@localhost:5432/synapse
REDIS_URL=redis://:${REDIS_PASSWORD}@localhost:6379

# AI Provider (required — no defaults, you must set these)
ANTHROPIC_API_KEY=
ANTHROPIC_BASE_URL=
AI_MODEL=
EOF

chmod 600 "$ENV_FILE"

echo "Generated .env at $ENV_FILE"
echo "Passwords have been auto-generated."
echo ""
echo "Next steps:"
echo "  1. Add your ANTHROPIC_API_KEY to .env"
echo "  2. Run: sudo docker compose up -d"
echo "  3. Start API: sudo systemctl restart synapse-api"
